ALTER TABLE layout_templates ADD COLUMN type text NOT NULL DEFAULT '董事会式',ADD COLUMN version integer NOT NULL DEFAULT 1,ADD COLUMN is_builtin boolean NOT NULL DEFAULT false;
ALTER TABLE rooms ADD COLUMN layout_template_id uuid REFERENCES layout_templates(id);
ON CONFLICT(name) DO NOTHING;
UPDATE rooms r SET layout_template_id=(SELECT id FROM layout_templates t WHERE t.type=r.data->>'type' ORDER BY is_builtin DESC,id LIMIT 1);
